// The base Transaction specification. Specifies properties that are common between all Transaction.
struct Transaction {
  // The Transaction's Identifier.
  std::optional<std::string> id; // wire: "id"
  // The date/time when the Transaction was created.
  std::optional<std::string> time; // wire: "time"
  // The ID of the user that initiated the creation of the Transaction.
  std::optional<std::int64_t> user_id; // wire: "userID"
  // The ID of the Account the Transaction was created for.
  std::optional<std::string> account_id; // wire: "accountID"
  // The ID of the "batch" that the Transaction belongs to. Transactions in the same batch are applied to the Account
  // simultaneously.
  std::optional<std::string> batch_id; // wire: "batchID"
  // The Request ID of the request which generated the transaction.
  std::optional<std::string> request_id; // wire: "requestID"
};

inline json::Value to_json(const Transaction &value) {
  json::Object object;
  if (value.id.has_value())
    object.emplace_back("id", json::encode(*value.id));
  if (value.time.has_value())
    object.emplace_back("time", json::encode(*value.time));
  if (value.user_id.has_value())
    object.emplace_back("userID", json::encode(*value.user_id));
  if (value.account_id.has_value())
    object.emplace_back("accountID", json::encode(*value.account_id));
  if (value.batch_id.has_value())
    object.emplace_back("batchID", json::encode(*value.batch_id));
  if (value.request_id.has_value())
    object.emplace_back("requestID", json::encode(*value.request_id));
  return json::Value(std::move(object));
}

