// An AccountState Object is used to represent an Account's current price-dependent state. Price-dependent Account state
// is dependent on OANDA's current Prices, and includes things like unrealized PL, NAV and Trailing Stop Loss Order
// state.
struct AccountChangesState {
  // The total unrealized profit/loss for all Trades currently open in the Account.
  std::optional<std::string> unrealized_pl; // wire: "unrealizedPL"
  // The net asset value of the Account. Equal to Account balance + unrealizedPL.
  std::optional<std::string> nav; // wire: "NAV"
  // Margin currently used for the Account.
  std::optional<std::string> margin_used; // wire: "marginUsed"
  // Margin available for Account currency.
  std::optional<std::string> margin_available; // wire: "marginAvailable"
  // The value of the Account's open positions represented in the Account's home currency.
  std::optional<std::string> position_value; // wire: "positionValue"
  // The Account's margin closeout unrealized PL.
  std::optional<std::string> margin_closeout_unrealized_pl; // wire: "marginCloseoutUnrealizedPL"
  // The Account's margin closeout NAV.
  std::optional<std::string> margin_closeout_nav; // wire: "marginCloseoutNAV"
  // The Account's margin closeout margin used.
  std::optional<std::string> margin_closeout_margin_used; // wire: "marginCloseoutMarginUsed"
  // The Account's margin closeout percentage. When this value is 1.0 or above the Account is in a margin closeout
  // situation.
  std::optional<std::string> margin_closeout_percent; // wire: "marginCloseoutPercent"
  // The value of the Account's open positions as used for margin closeout calculations represented in the Account's
  // home currency.
  std::optional<std::string> margin_closeout_position_value; // wire: "marginCloseoutPositionValue"
  // The current WithdrawalLimit for the account which will be zero or a positive value indicating how much can be
  // withdrawn from the account.
  std::optional<std::string> withdrawal_limit; // wire: "withdrawalLimit"
  // The Account's margin call margin used.
  std::optional<std::string> margin_call_margin_used; // wire: "marginCallMarginUsed"
  // The Account's margin call percentage. When this value is 1.0 or above the Account is in a margin call situation.
  std::optional<std::string> margin_call_percent; // wire: "marginCallPercent"
  // The price-dependent state of each pending Order in the Account.
  std::optional<std::vector<DynamicOrderState>> orders; // wire: "orders"
  // The price-dependent state for each open Trade in the Account.
  std::optional<std::vector<CalculatedTradeState>> trades; // wire: "trades"
  // The price-dependent state for each open Position in the Account.
  std::optional<std::vector<CalculatedPositionState>> positions; // wire: "positions"
};

