  // The current balance of the Account.
  std::optional<std::string> balance; // wire: "balance"
  // ID of the user that created the Account.
  std::optional<std::int64_t> created_by_user_id; // wire: "createdByUserID"
  // The date/time when the Account was created.
  std::optional<std::string> created_time; // wire: "createdTime"
  // The current guaranteed Stop Loss Order mode of the Account.
  std::optional<std::string> guaranteed_stop_loss_order_mode; // wire: "guaranteedStopLossOrderMode"
  // The total profit/loss realized over the lifetime of the Account.
