// An OrderFillTransaction represents the filling of an Order in the client's Account.
struct OrderFillTransaction {
  // The Transaction's Identifier.
  std::optional<std::string> id; // wire: "id"
  // The date/time when the Transaction was created.
  std::optional<std::string> time; // wire: "time"
  // The ID of the user that initiated the creation of the Transaction.
  std::optional<std::int64_t> user_id; // wire: "userID"
  // The ID of the Account the Transaction was created for.
  std::optional<std::string> account_id; // wire: "accountID"
  // The ID of the "batch" that the Transaction belongs to. Transactions in the same batch are applied to the Account
  // simultaneously.
  std::optional<std::string> batch_id; // wire: "batchID"
  // The Request ID of the request which generated the transaction.
  std::optional<std::string> request_id; // wire: "requestID"
  // The Type of the Transaction. Always set to "ORDER_FILL" for an OrderFillTransaction.
  std::optional<std::string> type; // wire: "type"
  // The ID of the Order filled.
  std::optional<std::string> order_id; // wire: "orderID"
  // The client Order ID of the Order filled (only provided if the client has assigned one).
  std::optional<std::string> client_order_id; // wire: "clientOrderID"
  // The name of the filled Order's instrument.
  std::optional<std::string> instrument; // wire: "instrument"
  // The number of units filled by the OrderFill.
  std::optional<std::string> units; // wire: "units"
  // This is the conversion factor in effect for the Account at the time of the OrderFill for converting any gains
  // realized in Instrument quote units into units of the Account's home currency.
  std::optional<std::string> gain_quote_home_conversion_factor; // wire: "gainQuoteHomeConversionFactor"
  // This is the conversion factor in effect for the Account at the time of the OrderFill for converting any losses
  // realized in Instrument quote units into units of the Account's home currency.
  std::optional<std::string> loss_quote_home_conversion_factor; // wire: "lossQuoteHomeConversionFactor"
  // This field is now deprecated and should no longer be used. The individual tradesClosed, tradeReduced and
  // tradeOpened fields contain the exact/official price each unit was filled at.
  std::optional<std::string> price; // wire: "price"
  // The price that all of the units of the OrderFill should have been filled at, in the absence of guaranteed price
  // execution. This factors in the Account's current ClientPrice, used liquidity and the units of the OrderFill only.
  // If no Trades were closed with their price clamped for guaranteed stop loss enforcement, then this value will match
  // the price fields of each Trade opened, closed, and reduced, and they will all be the exact same.
  std::optional<std::string> full_vwap; // wire: "fullVWAP"
  // The specification of an Account-specific Price.
  std::optional<ClientPrice> full_price; // wire: "fullPrice"
  // The reason that an Order was filled
  std::optional<std::string> reason; // wire: "reason"
  // The profit or loss incurred when the Order was filled.
  std::optional<std::string> pl; // wire: "pl"
  // The financing paid or collected when the Order was filled.
  std::optional<std::string> financing; // wire: "financing"
  // The commission charged in the Account's home currency as a result of filling the Order. The commission is always
  // represented as a positive quantity of the Account's home currency, however it reduces the balance in the Account.
  std::optional<std::string> commission; // wire: "commission"
  // The total guaranteed execution fees charged for all Trades opened, closed or reduced with guaranteed Stop Loss
  // Orders.
  std::optional<std::string> guaranteed_execution_fee; // wire: "guaranteedExecutionFee"
  // The Account's balance after the Order was filled.
  std::optional<std::string> account_balance; // wire: "accountBalance"
  // A TradeOpen object represents a Trade for an instrument that was opened in an Account. It is found embedded in
  // Transactions that affect the position of an instrument in the Account, specifically the OrderFill Transaction.
  std::optional<TradeOpen> trade_opened; // wire: "tradeOpened"
  // The Trades that were closed when the Order was filled (only provided if filling the Order resulted in a closing
  // open Trades).
  std::optional<std::vector<TradeReduce>> trades_closed; // wire: "tradesClosed"
  // A TradeReduce object represents a Trade for an instrument that was reduced (either partially or fully) in an
  // Account. It is found embedded in Transactions that affect the position of an instrument in the account,
  // specifically the OrderFill Transaction.
  std::optional<TradeReduce> trade_reduced; // wire: "tradeReduced"
  // The half spread cost for the OrderFill, which is the sum of the halfSpreadCost values in the tradeOpened,
  // tradesClosed and tradeReduced fields. This can be a positive or negative value and is represented in the home
  // currency of the Account.
  std::optional<std::string> half_spread_cost; // wire: "halfSpreadCost"
};

