// A StopLossOrderRejectTransaction represents the rejection of the creation of a StopLoss Order.
struct StopLossOrderRejectTransaction {
  // The Transaction's Identifier.
  std::optional<std::string> id; // wire: "id"
  // The date/time when the Transaction was created.
  std::optional<std::string> time; // wire: "time"
  // The ID of the user that initiated the creation of the Transaction.
  std::optional<std::int64_t> user_id; // wire: "userID"
  // The ID of the Account the Transaction was created for.
  std::optional<std::string> account_id; // wire: "accountID"
  // The ID of the "batch" that the Transaction belongs to. Transactions in the same batch are applied to the Account
  // simultaneously.
  std::optional<std::string> batch_id; // wire: "batchID"
  // The Request ID of the request which generated the transaction.
  std::optional<std::string> request_id; // wire: "requestID"
  // The Type of the Transaction. Always set to "STOP_LOSS_ORDER_REJECT" in a StopLossOrderRejectTransaction.
  std::optional<std::string> type; // wire: "type"
  // The ID of the Trade to close when the price threshold is breached.
  std::optional<std::string> trade_id; // wire: "tradeID"
  // The client ID of the Trade to be closed when the price threshold is breached.
  std::optional<std::string> client_trade_id; // wire: "clientTradeID"
  // The price threshold specified for the Stop Loss Order. If the guaranteed flag is false, the associated Trade will
  // be closed by a market price that is equal to or worse than this threshold. If the flag is true the associated Trade
  // will be closed at this price.
  std::optional<std::string> price; // wire: "price"
  // Specifies the distance (in price units) from the Account's current price to use as the Stop Loss Order price. If
  // the Trade is short the Instrument's bid price is used, and for long Trades the ask is used.
  std::optional<std::string> distance; // wire: "distance"
  // The time-in-force requested for the StopLoss Order. Restricted to "GTC", "GFD" and "GTD" for StopLoss Orders.
  std::optional<std::string> time_in_force; // wire: "timeInForce"
  // The date/time when the StopLoss Order will be cancelled if its timeInForce is "GTD".
  std::optional<std::string> gtd_time; // wire: "gtdTime"
  // Specification of which price component should be used when determining if an Order should be triggered and filled.
  // This allows Orders to be triggered based on the bid, ask, mid, default (ask for buy, bid for sell) or inverse (ask
  // for sell, bid for buy) price depending on the desired behaviour. Orders are always filled using their default price
  // component. This feature is only provided through the REST API. Clients who choose to specify a non-default trigger
  // condition will not see it reflected in any of OANDA's proprietary or partner trading platforms, their transaction
  // history or their account statements. OANDA platforms always assume that an Order's trigger condition is set to the
  // default value when indicating the distance from an Order's trigger price, and will always provide the default
  // trigger condition when creating or modifying an Order. A special restriction applies when creating a guaranteed
  // Stop Loss Order. In this case the TriggerCondition value must either be "DEFAULT", or the "natural" trigger side
  // "DEFAULT" results in. So for a Stop Loss Order for a long trade valid values are "DEFAULT" and "BID", and for short
  // trades "DEFAULT" and "ASK" are valid.
  std::optional<std::string> trigger_condition; // wire: "triggerCondition"
  // Flag indicating that the Stop Loss Order is guaranteed. The default value depends on the
  // GuaranteedStopLossOrderMode of the account, if it is REQUIRED, the default will be true, for DISABLED or ENABLED
  // the default is false.
  std::optional<bool> guaranteed; // wire: "guaranteed"
  // The reason that the Stop Loss Order was initiated
  std::optional<std::string> reason; // wire: "reason"
  // A ClientExtensions object allows a client to attach a clientID, tag and comment to Orders and Trades in their
  // Account. Do not set, modify, or delete this field if your account is associated with MT4.
  std::optional<ClientExtensions> client_extensions; // wire: "clientExtensions"
  // The ID of the OrderFill Transaction that caused this Order to be created (only provided if this Order was created
  // automatically when another Order was filled).
  std::optional<std::string> order_fill_transaction_id; // wire: "orderFillTransactionID"
  // The ID of the Order that this Order was intended to replace (only provided if this Order was intended to replace an
  // existing Order).
  std::optional<std::string> intended_replaces_order_id; // wire: "intendedReplacesOrderID"
  // The reason that the Reject Transaction was created
  std::optional<std::string> reject_reason; // wire: "rejectReason"
};

