// The specification of a Trade within an Account. This includes the full representation of the Trade's dependent Orders
// in addition to the IDs of those Orders.
struct Trade {
  // The Trade's identifier, unique within the Trade's Account.
  std::optional<std::string> id; // wire: "id"
  // The Trade's Instrument.
  std::optional<std::string> instrument; // wire: "instrument"
  // The execution price of the Trade.
  std::optional<std::string> price; // wire: "price"
  // The date/time when the Trade was opened.
  std::optional<std::string> open_time; // wire: "openTime"
  // The current state of the Trade.
  std::optional<std::string> state; // wire: "state"
  // The initial size of the Trade. Negative values indicate a short Trade, and positive values indicate a long Trade.
  std::optional<std::string> initial_units; // wire: "initialUnits"
  // The margin required at the time the Trade was created. Note, this is the 'pure' margin required, it is not the
  // 'effective' margin used that factors in the trade risk if a GSLO is attached to the trade.
  std::optional<std::string> initial_margin_required; // wire: "initialMarginRequired"
  // The number of units currently open for the Trade. This value is reduced to 0.0 as the Trade is closed.
  std::optional<std::string> current_units; // wire: "currentUnits"
  // The total profit/loss realized on the closed portion of the Trade.
  std::optional<std::string> realized_pl; // wire: "realizedPL"
  // The unrealized profit/loss on the open portion of the Trade.
  std::optional<std::string> unrealized_pl; // wire: "unrealizedPL"
  // Margin currently used by the Trade.
  std::optional<std::string> margin_used; // wire: "marginUsed"
  // The average closing price of the Trade. Only present if the Trade has been closed or reduced at least once.
  std::optional<std::string> average_close_price; // wire: "averageClosePrice"
  // The IDs of the Transactions that have closed portions of this Trade.
  std::optional<std::vector<std::string>> closing_transaction_ids; // wire: "closingTransactionIDs"
  // The financing paid/collected for this Trade.
  std::optional<std::string> financing; // wire: "financing"
  // The date/time when the Trade was fully closed. Only provided for Trades whose state is CLOSED.
  std::optional<std::string> close_time; // wire: "closeTime"
  // A ClientExtensions object allows a client to attach a clientID, tag and comment to Orders and Trades in their
  // Account. Do not set, modify, or delete this field if your account is associated with MT4.
  std::optional<ClientExtensions> client_extensions; // wire: "clientExtensions"
  // A TakeProfitOrder is an order that is linked to an open Trade and created with a price threshold. The Order will be
  // filled (closing the Trade) by the first price that is equal to or better than the threshold. A TakeProfitOrder
  // cannot be used to open a new Position.
  std::optional<TakeProfitOrder> take_profit_order; // wire: "takeProfitOrder"
  // A StopLossOrder is an order that is linked to an open Trade and created with a price threshold. The Order will be
  // filled (closing the Trade) by the first price that is equal to or worse than the threshold. A StopLossOrder cannot
  // be used to open a new Position.
  std::optional<StopLossOrder> stop_loss_order; // wire: "stopLossOrder"
  // A TrailingStopLossOrder is an order that is linked to an open Trade and created with a price distance. The price
  // distance is used to calculate a trailing stop value for the order that is in the losing direction from the market
  // price at the time of the order's creation. The trailing stop value will follow the market price as it moves in the
  // winning direction, and the order will filled (closing the Trade) by the first price that is equal to or worse than
  // the trailing stop value. A TrailingStopLossOrder cannot be used to open a new Position.
  std::optional<TrailingStopLossOrder> trailing_stop_loss_order; // wire: "trailingStopLossOrder"
};

